            if ((c.Num < CkRows[k * 5 + 1]) || (c.Num > CkRows[k * 5 + 2])) {
                CfFailRange(t, kf, ke, CkRows[k * 5 + 1], CkRows[k * 5 + 2], c);
                return 0;
            }
            CfSetNum(c, k, c.Num);
            return 1;
        }
        if (shape == ShEnum) {
            int code = CfWord(t, vf, vt, k);
            if (code < 0) {
                CfFailEnum(k, c);
                return 0;
            }
            CfSetWord(c, k, code);
            return 1;
        }
        if (shape == ShFlag) {
            CfSetFlag(c, k, CfOne(t, vf, vt));
            return 1;
        }
        if (shape == ShLimit) {
            int kind = CfLimitFind(t, kf + CkRows[k * 5 + 4], ke);
            if (kind < 0) {
                emon.Port.TextAscii(c.Msg, "no limit named ");
                CfPutSpan(t, kf + CkRows[k * 5 + 4], ke, c);
                return 0;
            }
            if (CfNum(t, vf, vt, c) == 0) {
                CfFailNum(t, kf, ke, vf, vt, c);
                return 0;
            }
            if ((c.Num < Limits.LmRows[kind * 5 + 1]) || (c.Num > Limits.LmRows[kind * 5 + 2])) {
                CfFailRange(t, kf, ke, Limits.LmRows[kind * 5 + 1], Limits.LmRows[kind * 5 + 2], c);
                return 0;
            }
            emon.Port.CellsPush(c.Lims, kind);
            emon.Port.CellsPush(c.Lims, c.Num);
            return 1;
        }
        int nf = kf + CkRows[k * 5 + 4];
        int q = 0;
        emon.Port.CellsPush(c.Prod, ke - nf);
        emon.Port.CellsPush(c.Prod, vt - vf);
        q = nf;
        while (q < ke) {
            emon.Port.CellsPush(c.Prod, emon.Port.CellsAt(t, q));
            q += 1;
